"""Visual-only ttk refinements; existing widgets keep their commands and states."""


_PALETTES = {'secondary': ('#192334', '#2f4160', '#222f45', '#131a27'), 'accent': ('#3d7ef5', '#3d7ef5', '#4c8dff', '#2f6be0'), 'danger': ('#141b28', '#5a2c32', '#2a1a1e', '#1f1416'), 'tab': ('#0e141d', '#0e141d', '#141b28', '#0e141d'), 'tab_selected': ('#0e141d', '#4c8dff', '#0e141d', '#0e141d'), 'popup': ('#0e141d', '#0e141d', '#192334', '#131a27'), 'popup_open': ('#16264a', '#16264a', '#1d3160', '#122040'), 'mode': ('#0b0f16', '#1c2638', '#121924', '#090d12'), 'mode_selected': ('#16264a', '#4c8dff', '#1b2d55', '#122040'), 'handover': ('#192334', '#2f4160', '#222f45', '#131a27'), 'handover_notice': ('#4a3b10', '#f2c35b', '#5a4815', '#3a2e0c')}


def install_visual_theme(window, style):
    """Install rounded ttk elements once, preserving every underlying control.

    Call after main, STL and wash styles have been initialized. Image references
    belong to the Tk root for the entire GUI lifetime. No external dependency is
    needed: the small antialiased PNG assets are embedded below.
    """
    import tkinter as tk

    previous = getattr(window, '_jihunius_visual_theme', None)
    if previous is not None:
        return previous
    images = {key: tk.PhotoImage(master=window, data=data, format='png')
              for key, data in _TILE_DATA.items()}
    # Ttk tiles the center; large flat tiles avoid thousands of tiny image blits.
    # Explicit24pxminimum keeps originalwidgetgeometry despite the largerassets.
    elements = set(style.element_names())

    def element(token, image_key, states=(), inset=0):
        name = 'JihuniusVisual.' + token
        if name not in elements:
            style.element_create(name, 'image', images[image_key],
                                 *[(spec, images[key]) for spec, key in states],
                                 border=8, padding=inset, width=24, height=24, sticky='nsew')
            elements.add(name)
        return name

    def button(name, palette, *, selected=False):
        states = [
            ('disabled', palette + '_disabled'),
            ('pressed', palette + '_pressed'),
            (('active', 'focus'), palette + '_focus_active'),
            ('focus', palette + '_focus'),
            ('active', palette + '_active'),
        ]
        if selected:
            states = [('disabled', palette + '_disabled'),
                      (('selected', 'pressed'), 'mode_selected_pressed'),
                      (('selected', 'focus'), 'mode_selected_focus'),
                      (('selected', 'active'), 'mode_selected_active'),
                      ('selected', 'mode_selected_normal')] + states[1:]
        border = element(name.replace('.', '_') + '.border', palette + '_normal', states)
        style.layout(name, [(border, {'sticky': 'nsew', 'children': [
            ('Button.padding', {'sticky': 'nsew', 'children': [
                ('Button.label', {'sticky': 'nsew'})]})]})])
        style.configure(name, borderwidth=0, relief='flat')

    for name, palette in (
        ('TButton', 'secondary'),
        ('Accent.TButton', 'accent'),
        ('Secondary.TButton', 'secondary'),
        ('Danger.TButton', 'danger'),
        ('DriveSmall.TButton', 'secondary'),
        ('AppTab.TButton', 'tab'),
        ('Selected.AppTab.TButton', 'tab_selected'),
        ('Popup.TButton', 'popup'),
        ('Open.Popup.TButton', 'popup_open'),
        ('HandoverToggle.TButton', 'handover'),
        ('HandoverNotice.TButton', 'handover_notice'),
        ('STL.Accent.TButton', 'accent'),
        ('STL.Secondary.TButton', 'secondary'),
        ('STL.Danger.TButton', 'danger'),
    ):
        button(name, palette)
    button('Mode.TRadiobutton', 'mode', selected=True)

    # Existing foreground semantics, notably notice amber and radio selection,
    # remain inherited from the original style definitions.
    style.configure('TButton', padding=(14, 7), foreground='#e7edf7')
    style.configure('Title.TLabel', font=('맑은 고딕', 20, 'bold'))
    style.map('TButton', foreground=[('disabled', '#96999e')])
    for name in ('AppTab.TButton', 'Selected.AppTab.TButton'):
        style.configure(name, padding=(18, 7), font=('맑은 고딕', 10, 'bold'))
    style.configure('AppTab.TButton', foreground='#8d95a3')
    style.configure('Selected.AppTab.TButton', foreground='#f2f4f7')
    for name in ('Popup.TButton', 'Open.Popup.TButton'):
        style.configure(name, padding=(14, 7), foreground='#aab2bf',
                        font=('맑은 고딕', 10, 'bold'))
        style.map(name, foreground=[('disabled', '#96999e')])
    style.configure('Open.Popup.TButton', foreground='#85b4ff')
    # A-3a: 팝업 버튼은 글자형이라 기본 최소 폭 없이 글자만큼만 차지합니다.
    style.configure('Popup.TButton', width=0)
    style.configure('Open.Popup.TButton', width=0)
    style.configure('HandoverToggle.TButton', background='#1f2b3f', foreground='#a7c9ff', padding=(16, 7))
    style.configure('HandoverNotice.TButton', background='#4a3b10', foreground='#ffd166', padding=(16, 7))
    style.map('HandoverToggle.TButton', background=[('active', '#2b3b56')])
    style.map('HandoverNotice.TButton', background=[('active', '#5a4815')])

    def field(name, kind):
        border = element(name.replace('.', '_') + '.field', 'field_normal', (
            ('disabled', 'field_disabled'), ('focus', 'field_focus')))
        if kind == 'entry':
            children = [('Entry.padding', {'sticky': 'nsew', 'children': [
                ('Entry.textarea', {'sticky': 'nsew'})]})]
        else:
            children = [
                ('Combobox.downarrow', {'side': 'right', 'sticky': 'ns'}),
                ('Combobox.padding', {'sticky': 'nsew', 'children': [
                    ('Combobox.textarea', {'sticky': 'nsew'})]})]
        style.layout(name, [(border, {'sticky': 'nsew', 'children': children})])
        style.configure(name, borderwidth=0, relief='flat', bordercolor='#405882',
                        lightcolor='#405882', darkcolor='#405882')

    field('TEntry', 'entry')
    field('STL.TEntry', 'entry')
    for name in ('TCombobox', 'Wash.TCombobox', 'STL.TCombobox'):
        field(name, 'combo')
        style.configure(name, arrowcolor='#c2c4c9', arrowsize=13,
                        background='#212d42', fieldbackground='#0b0f16')
        style.map(name, fieldbackground=[('disabled', '#202c41'), ('readonly', '#0b0f16')],
                  foreground=[('disabled', '#818388'), ('readonly', '#e7edf7')],
                  selectbackground=[('readonly', '#0b0f16')],
                  selectforeground=[('readonly', '#e7edf7')])

    for name, key in (('RoundedCard.TFrame', 'card'), ('NavRail.TFrame', 'nav')):
        border = element(name.replace('.', '_') + '.border', key)
        style.layout(name, [(border, {'sticky': 'nsew'})])
        style.configure(name, background='#141b28' if key == 'card' else '#0e141d', borderwidth=0)
    # Flat Card.TFrame remains untouched, including inner borderwidth=0 frames.
    badge = element('status.border', 'status', inset=6)
    style.layout('Status.TLabel', [(badge, {'sticky': 'nsew', 'children': [
        ('Label.padding', {'sticky': 'nsew', 'children': [
            ('Label.label', {'sticky': 'nsew'})]})]})])
    style.configure('Status.TLabel', background='#203657', foreground='#a7c9ff',
                    padding=(8, 1), borderwidth=0)
    style.configure('CardTitle.TLabel', background='#141b28', foreground='#e7edf7',
                    font=('맑은 고딕', 20, 'bold'))
    for name in ('Vertical.TScrollbar', 'Horizontal.TScrollbar'):
        style.map(name, background=[('pressed', '#717378'), ('active', '#405881')])
    # All action buttons share typography and vertical rhythm. Keep each
    # palette/state map, including handover and update notices, unchanged.
    for name in ('TButton', 'Accent.TButton', 'Secondary.TButton',
                 'Danger.TButton', 'DriveSmall.TButton', 'AppTab.TButton',
                 'Selected.AppTab.TButton', 'Popup.TButton', 'Open.Popup.TButton',
                 'HandoverToggle.TButton', 'HandoverNotice.TButton',
                 'STL.Accent.TButton', 'STL.Secondary.TButton', 'STL.Danger.TButton',
                 'Mode.TRadiobutton'):
        style.configure(name, font=('맑은 고딕', 10, 'normal'), padding=(10, 7))
    style.configure('DriveSmall.TButton', padding=(6, 7))
    # 인수인계는 탭 줄 가운데에 조금 더 크게 둡니다.
    for name in ('HandoverToggle.TButton', 'HandoverNotice.TButton'):
        style.configure(name, padding=(24, 9))
    style.configure('Title.TLabel', font=('맑은 고딕', 18, 'bold'))
    style.configure('TEntry', padding=(10, 6))
    for name in ('Accent.TButton', 'STL.Accent.TButton'):
        style.map(name, foreground=[('disabled', '#818388'), ('!disabled', '#ffffff')])
    style.map('Mode.TRadiobutton', foreground=[('disabled', '#818388'), ('selected', '#ffffff'), ('!selected', '#8d95a3')])

    for name in ('Accent.TButton', 'Selected.AppTab.TButton', 'HandoverNotice.TButton'):
        style.configure(name, font=('맑은 고딕', 10, 'bold'))
    for name in ('HandoverToggle.TButton', 'HandoverNotice.TButton'):
        style.configure(name, font=('맑은 고딕', 11, 'bold'))
    result = {'popup_icon': images['popup_icon'], 'images': images}
    window._jihunius_visual_theme = result
    return result




def install_companion_buttons(window, style, names):
    """Reuse native ttk interaction and existing padding/font in companion roots."""
    import tkinter as tk
    images = {}
    elements = set(style.element_names())
    for name, palette, foreground in names:
        for state in ('normal', 'active', 'pressed', 'disabled', 'focus'):
            key = palette + '_' + state
            if key not in images:
                images[key] = tk.PhotoImage(master=window, data=_TILE_DATA[key], format='png')
        token = 'JihuniusCompanion.' + name.replace('.', '_')
        if token not in elements:
            # Preserve clam's two-pixel border and each style's focus inset.
            # Image slicing borders must not enlarge existing buttons.
            focus_inset = style.lookup(name, 'focusthickness')
            inset = 2 + (int(focus_inset) if focus_inset != '' else 1)
            style.element_create(token, 'image', images[palette+'_normal'],
                                 ('disabled', images[palette+'_disabled']),
                                 ('pressed', images[palette+'_pressed']),
                                 ('focus', images[palette+'_focus']),
                                 ('active', images[palette+'_active']),
                                 border=8, padding=inset, width=24, height=24, sticky='nsew')
            elements.add(token)
        style.layout(name, [(token, {'sticky':'nsew','children':[
            ('Button.padding', {'sticky':'nsew','children':[('Button.label',{'sticky':'nsew'})]})]})])
        style.configure(name, foreground=foreground, borderwidth=0, relief='flat')
        style.map(name, foreground=[('disabled','#818388'),('!disabled',foreground)])
    window._jihunius_companion_tiles = images

_TILE_DATA = {'secondary_normal': '', 'secondary_active': '', 'secondary_pressed': '', 'secondary_disabled': '', 'secondary_focus': '', 'secondary_focus_active': '', 'accent_normal': '', 'accent_active': '', 'accent_pressed': '', 'accent_disabled': '', 'accent_focus': '', 'accent_focus_active': '', 'danger_normal': '', 'danger_active': '', 'danger_pressed': '', 'danger_disabled': '', 'danger_focus': '', 'danger_focus_active': '', 'tab_normal': '', 'tab_active': '', 'tab_pressed': '', 'tab_disabled': '', 'tab_focus': '', 'tab_focus_active': '', 'tab_selected_normal': '', 'tab_selected_active': '', 'tab_selected_pressed': '', 'tab_selected_disabled': '', 'tab_selected_focus': '', 'tab_selected_focus_active': '', 'popup_normal': '', 'popup_active': '', 'popup_pressed': '', 'popup_disabled': '', 'popup_focus': '', 'popup_focus_active': '', 'popup_open_normal': '', 'popup_open_active': '', 'popup_open_pressed': '', 'popup_open_disabled': '', 'popup_open_focus': '', 'popup_open_focus_active': '', 'mode_normal': '', 'mode_active': '', 'mode_pressed': '', 'mode_disabled': '', 'mode_focus': '', 'mode_focus_active': '', 'mode_selected_normal': '', 'mode_selected_active': '', 'mode_selected_pressed': '', 'mode_selected_disabled': '', 'mode_selected_focus': '', 'mode_selected_focus_active': '', 'handover_normal': '', 'handover_active': '', 'handover_pressed': '', 'handover_disabled': '', 'handover_focus': '', 'handover_focus_active': '', 'handover_notice_normal': '', 'handover_notice_active': '', 'handover_notice_pressed': '', 'handover_notice_disabled': '', 'handover_notice_focus': '', 'handover_notice_focus_active': '', 'field_normal': '', 'field_disabled': '', 'field_focus': '', 'card': '', 'nav': '', 'status': '', 'popup_icon': '', 'defect_icon': '', 'defect_icon_disabled': '', 'rotate_icon': '', 'rotate_icon_disabled': ''}
